import {
    Table,
    StringColumn,
    BooleanColumn,
    ReferenceColumn,
    IntegerColumn,
    DecimalColumn,
    GuidColumn,
    GenericColumn,
    DateTimeColumn,
    ListColumn,
    DomainPathColumn,
    ChoiceColumn,
    DomainIdColumn,
    SystemClassNameColumn,
} from '@servicenow/sdk/core'

export const cmdb_model = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    display: 'display_name',
    extensible: true,
    label: 'Product Model',
    name: 'cmdb_model',
    schema: {
        status: StringColumn({
            default: 'In Production',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Indicates whether the model is active or retired',
                    label: 'Status',
                    plural: 'Status',
                    language: 'en',
                },
            ],
        }),
        certified: BooleanColumn({
            label: [
                {
                    hint: 'Indicates whether the model has been approved for use',
                    label: 'Certified',
                    plural: 'Certified',
                    language: 'en',
                },
            ],
        }),
        owner: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Person responsible for the model',
                    label: 'Owner',
                    plural: 'Owners',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
            referenceFloats: true,
        }),
        weight: IntegerColumn({
            label: [
                {
                    hint: 'Weight of the hardware model, expressed in pounds',
                    label: 'Weight (lbs)',
                    plural: 'Weight (lbs)',
                    language: 'en',
                },
            ],
        }),
        length: DecimalColumn({
            label: [
                {
                    hint: 'Length of the model, expressed in dimension units selected',
                    label: 'Length',
                    plural: 'Lengths',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        voltage: DecimalColumn({
            label: [
                {
                    hint: 'Voltage apparent for the model, expressed in units selected',
                    label: 'Voltage',
                    plural: 'Voltages',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        typical_energy_consumption: DecimalColumn({
            scale: 7,
            label: [
                {
                    hint: 'Typical electricity consumed by a product while in normal operation during an year',
                    label: 'Typical energy consumption (kWh)',
                    plural: 'Typical energy consumption (kWh)',
                    language: 'en',
                },
            ],
            maxLength: 22,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        name: StringColumn({
            label: [
                {
                    hint: 'Name of the model',
                    label: 'Name',
                    plural: 'Names',
                    language: 'en',
                },
            ],
            maxLength: 255,
        }),
        cmdb_ci_class: StringColumn({
            label: [
                {
                    hint: '--- Deprecated ---',
                    label: 'CMDB CI class',
                    plural: 'CMDB CI class',
                    language: 'en',
                },
            ],
        }),
        cost: GenericColumn({
            attributes: {
                serializer: 'com.glide.script.PriceXMLSerializer',
            },
            columnType: 'price',
            label: [
                {
                    hint: 'Cost of one unit of the model',
                    label: 'Cost',
                    plural: 'Costs',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        product_catalog_item: ReferenceColumn({
            attributes: {
                readonly_clickthrough: true,
            },
            label: [
                {
                    hint: 'the catalog item item that was created when it was published',
                    label: 'Catalog Item',
                    plural: 'Catalog Items',
                    language: 'en',
                },
            ],
            readOnly: true,
            referenceTable: 'sc_cat_item',
        }),
        flow_rate: IntegerColumn({
            label: [
                {
                    hint: 'Flow rate of the hardware model, expressed in cubic feet per minute',
                    label: 'Flow Rate (cfm)',
                    plural: 'Flow Rate (cfm)',
                    language: 'en',
                },
            ],
        }),
        depth: DecimalColumn({
            label: [
                {
                    hint: 'Depth of the model, expressed in dimension units selected',
                    label: 'Depth',
                    plural: 'Depths',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        current: DecimalColumn({
            label: [
                {
                    hint: 'Current apparent for the model, expressed in units selected',
                    label: 'Current',
                    plural: 'Currents',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        transportation_emission: DecimalColumn({
            scale: 7,
            label: [
                {
                    hint: 'Emissions from shipping and distribution throughout the supply chain for the product',
                    label: 'Transportation emission (kgCO2e)',
                    plural: 'Transportation emission (kgCO2e)',
                    language: 'en',
                },
            ],
            maxLength: 22,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        manufacturer: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Manufacturer of the model',
                    label: 'Manufacturer',
                    plural: 'Manufacturers',
                    language: 'en',
                },
            ],
            referenceTable: 'core_company',
            referenceQual: 'manufacturer=true^EQ',
        }),
        cmdb_model_category: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            cascadeRule: 'restrict',
            label: [
                {
                    hint: 'Model categories the model can be associated with for creation of configuration items and/or assets',
                    label: 'Model categories',
                    plural: 'Model categories',
                    language: 'en',
                },
            ],
            maxLength: 1024,
            referenceTable: 'cmdb_model_category',
        }),
        salvage_value: GenericColumn({
            attributes: {
                omit_sys_original: true,
            },
            columnType: 'currency',
            label: [
                {
                    hint: 'Estimated residual value of an asset',
                    label: 'Salvage value',
                    plural: 'Salvage values',
                    language: 'en',
                },
            ],
            maxLength: 20,
        }),
        picture: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'picture of the product model',
                    label: 'Picture',
                    plural: 'Pictures',
                    language: 'en',
                },
            ],
        }),
        expected_lifetime_co2e: StringColumn({
            label: [
                {
                    hint: 'Expected lifetime CO2e',
                    label: 'Expected lifetime CO2e',
                    plural: 'Expected lifetime CO2es',
                    language: 'en',
                },
            ],
        }),
        weight_decimal: DecimalColumn({
            label: [
                {
                    hint: 'Weight of the model, expressed in units selected',
                    label: 'Weight',
                    plural: 'Weights',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        volume: DecimalColumn({
            label: [
                {
                    hint: 'Volume of the model, expressed in units selected',
                    label: 'Volume',
                    plural: 'Volumes',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        eol_emission: DecimalColumn({
            scale: 7,
            label: [
                {
                    hint: 'Emissions from disposal, recycling, or refurbishment processes of the product',
                    label: 'End-of-life emission (kgCO2e)',
                    plural: 'End-of-life emission (kgCO2e)',
                    language: 'en',
                },
            ],
            maxLength: 22,
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        sla: StringColumn({
            label: [
                {
                    hint: 'Service Level Agreement for servicing items of the model',
                    label: 'SLA',
                    plural: 'SLAs',
                    language: 'en',
                },
            ],
            maxLength: 30,
        }),
        bundle: BooleanColumn({
            label: [
                {
                    hint: 'When true, the model record represents a bundle. Bundles can be abstract with a category of Bundle and no direct instanciation as CI or asset, or concrete with direct instanciation',
                    label: 'Bundle',
                    plural: 'Bundles',
                    language: 'en',
                },
            ],
        }),
        asset_tracking_strategy: StringColumn({
            default: 'leave_to_category',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Allows to override the way assets are tracked for the model',
                    label: 'Asset tracking strategy',
                    plural: 'Asset tracking strategys',
                    language: 'en',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            label: [
                {
                    label: 'Domain path',
                    plural: 'Domain Paths',
                    language: 'en',
                },
            ],
        }),
        energy_star: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Energy Star certified',
                    label: 'Energy Star',
                    plural: 'Energy Stars',
                    language: 'en',
                },
            ],
        }),
        rated_power: DecimalColumn({
            label: [
                {
                    hint: 'Power apparent for the model, expressed in units selected',
                    label: 'Rated Power',
                    plural: 'Rated Powers',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        unit_of_measure_system: ChoiceColumn({
            default: 'us imperial',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Unit of Measure system which is used for this model',
                    label: 'Unit of Measure System',
                    plural: 'Unit of Measure Systems',
                    language: 'en',
                },
            ],
        }),
        model_number: StringColumn({
            label: [
                {
                    hint: 'Number identifying the model, defined internally or by the manufacturer',
                    label: 'Model number',
                    plural: 'Model numbers',
                    language: 'en',
                },
            ],
            maxLength: 80,
        }),
        comments: StringColumn({
            label: [
                {
                    hint: 'Additional information about the model',
                    label: 'Comments',
                    plural: 'Comments',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        expenditure_type: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Expenditure type',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the data belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        energy_use: StringColumn({
            label: [
                {
                    hint: 'Energy use',
                    label: 'Energy use',
                    plural: 'Energy use',
                    language: 'en',
                },
            ],
        }),
        weight_unit: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            dependent: 'unit_of_measure_system',
            label: [
                {
                    hint: 'Unit of measure for weight',
                    label: 'Weight unit',
                    plural: 'Weight units',
                    language: 'en',
                },
            ],
        }),
        volume_unit: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            dependent: 'unit_of_measure_system',
            label: [
                {
                    hint: 'Unit of measure for volume',
                    label: 'Volume unit',
                    plural: 'Volume units',
                    language: 'en',
                },
            ],
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        short_description: StringColumn({
            label: [
                {
                    hint: 'Short description of the model',
                    label: 'Short description',
                    plural: 'Short descriptions',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        main_component: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Used only when model represents an abstract bundle : reference to the model whose instanciation will carry the components when such a model is defined',
                    label: 'Main component',
                    plural: 'Main components',
                    language: 'en',
                },
            ],
            readOnly: true,
            referenceTable: 'cmdb_m2m_model_component',
        }),
        asset_tracking_unit: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            default: 'individual unit',
            label: [
                {
                    hint: 'Unit of measure for asset',
                    label: 'Asset tracking unit',
                    plural: 'Asset tracking units',
                    language: 'en',
                },
            ],
            referenceTable: 'cmdb_model_unit',
        }),
        rack_units: IntegerColumn({
            default: '1',
            label: [
                {
                    hint: 'Height of the hardware model, expressed in number of rack units',
                    label: 'Height (U)',
                    plural: 'Height (U)',
                    language: 'en',
                },
            ],
        }),
        height: DecimalColumn({
            label: [
                {
                    hint: 'Height of the model, expressed in dimension units selected',
                    label: 'Height',
                    plural: 'Heights',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        power_unit: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Unit of measure for Power values',
                    label: 'Power unit',
                    plural: 'Power units',
                    language: 'en',
                },
            ],
        }),
        expected_lifespan: DecimalColumn({
            scale: 2,
            label: [
                {
                    hint: 'Duration a product remains functional and efficient as provided by the manufacturer in years',
                    label: 'Expected lifespan',
                    plural: 'Expected lifespans',
                    language: 'en',
                },
            ],
            maxLength: 17,
        }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Type of the model (base, hardware, software, ...)',
                    label: 'Class',
                    plural: 'Class',
                    language: 'en',
                },
            ],
            maxLength: 80,
        }),
        barcode: StringColumn({
            label: [
                {
                    hint: 'Barcode identifying the model',
                    label: 'Barcode',
                    plural: 'Barcodes',
                    language: 'en',
                },
            ],
        }),
        acquisition_method: StringColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'How assets or configuration items of the model are typically procured',
                    label: 'Acquisition method',
                    plural: 'Acquisition methods',
                    language: 'en',
                },
            ],
        }),
        type: StringColumn({
            default: 'Generic',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Indicates whether the model represent an actual product model that can be purchased (Product) or an internal abstract model representing several actual product models (Generic)',
                    label: 'Type',
                    plural: 'Types',
                    language: 'en',
                },
            ],
        }),
        power_consumption: IntegerColumn({
            label: [
                {
                    hint: 'Power consumption of the hardware model, expressed in Watts',
                    label: 'Power (watts)',
                    plural: 'Power (watts)',
                    language: 'en',
                },
            ],
        }),
        width: DecimalColumn({
            label: [
                {
                    hint: 'Width of the model, expressed in dimension units selected',
                    label: 'Width',
                    plural: 'Widths',
                    language: 'en',
                },
            ],
            maxLength: 15,
        }),
        voltage_unit: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Unit of measure for voltage',
                    label: 'Voltage unit',
                    plural: 'Voltage units',
                    language: 'en',
                },
            ],
        }),
        manufacturing_emission: DecimalColumn({
            scale: 7,
            label: [
                {
                    hint: 'Emissions from raw material extraction, production, and assembly of the product',
                    label: 'Manufacturing emission (kgCO2e)',
                    plural: 'Manufacturing emission (kgCO2e)',
                    language: 'en',
                },
            ],
            maxLength: 22,
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        display_name: StringColumn({
            label: [
                {
                    hint: 'Display name of the model, dependent on Name and Manufacturer',
                    label: 'Display name',
                    plural: 'Display names',
                    language: 'en',
                },
            ],
            maxLength: 255,
            readOnly: true,
        }),
        full_name: StringColumn({
            label: 'Full name',
            maxLength: 100,
        }),
        depreciation: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'restrict',
            label: [
                {
                    hint: 'Depreciation scheme the model follows',
                    label: 'Depreciation',
                    plural: 'Depreciations',
                    language: 'en',
                },
            ],
            referenceTable: 'cmdb_depreciation',
        }),
        description: GenericColumn({
            attributes: {
                encode_utf8: false,
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            columnType: 'translated_html',
            label: [
                {
                    hint: 'html formated description',
                    label: 'Description',
                    plural: 'Descriptions',
                    language: 'en',
                },
            ],
            maxLength: 8000,
        }),
        sound_power: IntegerColumn({
            label: [
                {
                    hint: 'Sound power of the hardware model, expressed in bels',
                    label: 'Sound Power (bels)',
                    plural: 'Sound Power (bels)',
                    language: 'en',
                },
            ],
        }),
        dimensions_unit: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            dependent: 'unit_of_measure_system',
            label: [
                {
                    hint: 'Unit of measure for dimensions',
                    label: 'Dimensions Unit',
                    plural: 'Dimensions Units',
                    language: 'en',
                },
            ],
        }),
        current_unit: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Unit of measure for Current values',
                    label: 'Current Unit',
                    plural: 'Current Units',
                    language: 'en',
                },
            ],
        }),
        usage_emission: DecimalColumn({
            scale: 7,
            label: [
                {
                    hint: "Emissions during the product's usage phase",
                    label: 'Usage emission (kgCO2e)',
                    plural: 'Usage emission (kgCO2e)',
                    language: 'en',
                },
            ],
            maxLength: 22,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        life_cycle_stage_status: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Life Cycle Stage Status',
            maxLength: 40,
            referenceTable: 'life_cycle_stage_status',
            referenceKey: 'name',
            referenceQual: 'javascript: new LifeCycleUtil().filterLifeCycleStageStatus()',
        }),
        life_cycle_stage: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Life Cycle Stage',
            maxLength: 40,
            referenceTable: 'life_cycle_stage',
            referenceKey: 'name',
            referenceQual: 'javascript: new LifeCycleUtil().filterLifeCycleStage()',
        }),
    },
})
